insert into documents (tenant_id, id, title, category, updated, summary, related, source, owner) values
  ('11111111-1111-4111-8111-111111111111', 'DOC-01', 'Vehicle walkaround check procedure', 'Fleet', '2026-09-12', 'Sets out the daily walkaround check every driver completes before first use of a vehicle: tyres and wheel security, lights, mirrors and cameras, brakes and air lines, leaks, bodywork and load security, windscreen and wipers, and dashboard warnings. Any safety-critical defect means the vehicle must not be used until assessed by the transport office.', array['DEF-001']::text[], 'SharePoint — proposed source (not connected)', 'Transport Manager'),
  ('11111111-1111-4111-8111-111111111111', 'DOC-02', 'Defect reporting and VOR process', 'Fleet', '2026-08-30', 'How defects are reported, graded (safety-critical or minor), assessed and rectified. Covers when a vehicle is declared Vehicle Off Road (VOR), who can return it to service, and the record that must be kept.', array['ACT-002']::text[], 'SharePoint — proposed source (not connected)', 'Transport Manager'),
  ('11111111-1111-4111-8111-111111111111', 'DOC-03', 'Drivers'' hours and working time policy', 'Compliance', '2026-07-18', 'Company policy on EU/AETR drivers'' hours, Working Time Directive limits, breaks and rest. Planning tools give an estimate only; the tachograph record and the driver''s own judgement remain the authority.', array[]::text[], 'SharePoint — proposed source (not connected)', 'Transport Manager'),
  ('11111111-1111-4111-8111-111111111111', 'DOC-04', 'Licence checking policy', 'Compliance', '2026-06-04', 'Licence evidence is reviewed for every driver at least annually and more often for drivers with endorsements. Reviews are recorded with date, method and reviewer.', array['CMP-01']::text[], 'SharePoint — proposed source (not connected)', 'Transport Manager'),
  ('11111111-1111-4111-8111-111111111111', 'DOC-05', 'Infringement debrief procedure', 'Compliance', '2026-05-21', 'Each tachograph infringement is discussed with the driver, recorded, and signed by both driver and transport manager within seven days.', array['ACT-003','CMP-02']::text[], 'SharePoint — proposed source (not connected)', 'Transport Manager'),
  ('11111111-1111-4111-8111-111111111111', 'DOC-06', 'POD capture and submission', 'Operations', '2026-09-02', 'Proof of delivery must be signed and photographed at the customer site and submitted before the driver leaves. Missing PODs block invoicing.', array['ACT-001']::text[], 'SharePoint — proposed source (not connected)', 'Operations'),
  ('11111111-1111-4111-8111-111111111111', 'DOC-07', 'Waiting time and detention charging', 'Commercial', '2026-04-15', 'Customers receive one hour of free time per drop. Waiting beyond this is chargeable at the detention rate in the customer schedule, subject to timed evidence from the driver app or telematics.', array[]::text[], 'SharePoint — proposed source (not connected)', 'Operations'),
  ('11111111-1111-4111-8111-111111111111', 'DOC-08', 'Fuel card use and reconciliation', 'Finance', '2026-03-10', 'Rules for fuel card use, receipts and weekly reconciliation. Supplier to be confirmed for the portal integration.', array[]::text[], 'SharePoint — proposed source (not connected)', 'Operations'),
  ('11111111-1111-4111-8111-111111111111', 'DOC-09', 'Customer delivery notifications', 'Operations', '2026-10-01', 'Which customer contacts receive delivery notifications, how one-time links work, and how contacts can opt out.', array[]::text[], 'SharePoint — proposed source (not connected)', 'Operations'),
  ('11111111-1111-4111-8111-111111111111', 'DOC-10', 'Agency driver induction checklist', 'HR', '2026-02-26', 'Site induction, licence and CPC evidence, tachograph card check and vehicle familiarisation for agency drivers before their first shift.', array[]::text[], 'SharePoint — proposed source (not connected)', 'Operations');
